const $=s=>document.querySelector(s), app=$('#app');let avatar=null, page='Home', mealData=[], readings=[], records=[], labResults=[], capabilities={}, nutritionDay=localDay(), connections=[], connectionError="", lastFocus, authMode='login',bodyView='portrait',appearance={skinColor:'#c8cbb9'};
let journalData=[],journalError='',chatOpen=false;
let profile=null,portraitURL=null,portraitChecked=0,peerResult=null;
let boardDraft=null,boardSaving=false,syncState={busy:false,error:null};
const paths={refresh:'M20 7V3l-3 3a8 8 0 1 0 3 9 M20 3v5h-5',chat:'M4 4h16v13H9l-5 4z M8 8h8 M8 12h5',peers:'M4 20v-6h4v6 M10 20V4h4v16 M16 20V9h4v11',home:'M3 10 12 3l9 7v11H3z M9 21v-8h6v8',vitals:'M2 12h4l3-8 4 16 3-8h6',body:'M12 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M7 11l5-2 5 2 M12 9v7 M7 21l5-5 5 5 M7 11l-2 5 M17 11l2 5',food:'M5 3v6q0 3 3 3V3 M8 12v9 M19 3q-6 4-3 10h3 M19 3v18',sleep:'M20 14A8 8 0 0 1 10 4a9 9 0 1 0 10 10z',report:'M5 3h10l4 4v14H5z M15 3v5h4 M8 12h8 M8 16h6',link:'m9 15 6-6 M8 17l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 7l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',arrow:'M6 18 18 6 M7 6h11v11',plus:'M12 5v14 M5 12h14',close:'m6 6 12 12 M18 6 6 18',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5',leaf:'M20 3q-18-2-16 11t14-1z M4 20 16 7',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',camera:'M3 6h5l2-3h4l2 3h5v15H3z M12 9a4 4 0 1 0 0 8 4 4 0 0 0 0-8',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',trash:'M4 6h16 M9 3h6 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',shield:'M12 2 3 6v6q0 6 9 10 9-4 9-10V6z M8 12l3 3 5-6',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',download:'M12 3v13 M7 11l5 5 5-5 M3 18v3h18v-3'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.vitals}"/></svg>`;
const orb=brandOrb;
const button=(text,action,cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${text}</button>`;
const navs=[['Home','home'],['Vitals','vitals'],['Body','body'],['Nutrition','food'],['Journal','report'],['Sleep','sleep'],['Blood records','report']];

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function dispose(){avatar?.dispose();avatar=null}
function err(e){toast(e.message||'Something went wrong. Please try again.')}
async function mountModel(){dispose();const el=$('#avatar-host');if(el){try{const {mountAvatar}=await import('./avatar.js');if(el.isConnected)avatar=mountAvatar(el,appearance)}catch(e){if(el.isConnected)el.innerHTML='<p class="mini-note">The 3D view could not load. Please try again.</p>'}}}
function seriesChart(rows,stroke='#8ca883',average=null){
 if(rows.length<2)return '<div class="chart-empty">'+(rows.length?'One recorded measurement':'No measurements in this period')+'</div>';
 const values=rows.map(r=>Number(r.value)),min=Math.min(...values),max=Math.max(...values),span=max-min||1;
 const start=Date.parse(rows[0].observed_at),duration=Date.parse(rows.at(-1).observed_at)-start||1;
 const points=rows.map(r=>`${((Date.parse(r.observed_at)-start)/duration*236+2).toFixed(2)},${(48-(Number(r.value)-min)/span*38).toFixed(2)}`).join(' ');
 return `<svg class="spark" viewBox="0 0 240 55" preserveAspectRatio="none" role="img" aria-label="${rows.length} recorded measurements">${average!==null?`<line class="average-guide" x1="0" x2="240" y1="${48-(average-min)/span*38}" y2="${48-(average-min)/span*38}" stroke="${stroke}" stroke-opacity=".5" stroke-dasharray="4 4"/>`:""}<polyline points="${points}" stroke="${stroke}" fill="none" stroke-width="1.5"/></svg>`;
}
function reading(k){return readings.find(r=>r.kind===k)}
function cardChart(rows,m){
 const recent=rows.slice(-21);if(recent.length<2)return seriesChart(recent,m.stroke);
 const values=recent.map(r=>Number(r.value)),max=Math.max(...values)||1;
 if(['hrv','hrv_sdnn','sleep','sleep_deep','sleep_rem','sleep_light','steps'].includes(m.kind))return `<div class="metric-bars" role="img" aria-label="${recent.length} recorded measurements">${recent.map((r,i)=>`<i style="--bar:${Math.max(4,Number(r.value)/max*100)}%;--bar-color:${m.stroke};--bar-opacity:${.4+i/recent.length*.6}" title="${new Date(r.observed_at).toLocaleDateString('en-US')}: ${formatValue(r.value,m.kind)} ${m.unit}"></i>`).join('')}</div>`;
 const min=Math.min(...values),span=max-min||1,start=Date.parse(recent[0].observed_at),duration=Date.parse(recent.at(-1).observed_at)-start||1,points=recent.map(r=>`${((Date.parse(r.observed_at)-start)/duration*236+2).toFixed(2)},${(46-(Number(r.value)-min)/span*32).toFixed(2)}`).join(' '),last=points.split(' ').at(-1).split(',');
 return `<svg class="spark" viewBox="0 0 240 55" preserveAspectRatio="none" role="img" aria-label="${recent.length} recorded measurements"><defs><linearGradient id="fade-${m.kind}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${m.stroke}" stop-opacity=".22"/><stop offset="1" stop-color="${m.stroke}" stop-opacity="0"/></linearGradient></defs><path d="M2 55 L${points.replaceAll(' ',' L')} L238 55Z" fill="url(#fade-${m.kind})" stroke="none"/><polyline points="${points}" stroke="${m.stroke}" fill="none" stroke-width="1.5" vector-effect="non-scaling-stroke"/><circle cx="${last[0]}" cy="${last[1]}" r="2.4" fill="${m.stroke}" stroke="#fff" stroke-width="1.3"/></svg>`;
}
function cards(list=metrics,compact=false){return list.map(m=>{const r=reading(m.kind),series=metricSeries(readings.filter(x=>x.source===r?.source&&x.unit===r?.unit),m.kind),average=metricSummary(series),date=r?new Date(r.observed_at).toLocaleDateString('en-US',{month:'short',day:'numeric'}):'';return `<button class="metric ${m.color} ${compact?'dashboard-metric':''}" data-metric="${m.kind}" ${r?`title="${esc(r.source)} · ${date} · ${average.days} recorded days in the last 30"`:''}><div class="metric-top">${m.name}${icon('arrow')}</div><div class="metric-number">${r?formatValue(r.value,m.kind):'—'}<small>${m.unit}</small></div>${!compact?`<div class="metric-source">${r?esc(r.source):m.group==='body'?'Add your measurement':'No reading yet'}</div>`:''}${r?cardChart(series,m):`<div class="chart-empty">${m.group==='body'?'Add a measurement to get started':'Connect a source to get started'}</div>`}${compact?`<div class="metric-meta"><span>${average.mean!==null?`30d avg <strong>${formatValue(average.mean,m.kind)}</strong>`:'No reading yet'}</span><span class="metric-origin">${r?esc(r.source):m.group==='body'?'Add entry':'Connect ↗'}</span></div>`:`${average.mean!==null?`<div class="metric-average"><span>30-day avg</span><strong>${formatValue(average.mean,m.kind)} <small>${esc(m.unit)}</small></strong><span>${average.days}d recorded</span></div>`:''}<div class="metric-footer"><span>${date||'Awaiting data'}</span><span>${r?'View trend':m.group==='body'?'Add entry':'Connect'}</span></div>`}</button>`}).join('')}

function vitalsPage(){const available=metrics.filter(m=>m.group!=='sleep'&&m.group!=='body'&&reading(m.kind));return `<div class="page-top"><div><h2>A closer look at your signals.</h2><p>${available.length} available measurements from your connected sources.</p></div><button class="btn light" data-nav="Integrations">Manage sources ${icon('arrow')}</button></div><div class="metric-grid full">${cards(available.length?available:metrics.slice(0,6).filter(m=>m.kind!=='sleep'))}</div>`}
function sleepPage(){const latest=reading('sleep'),stages=[['sleep_deep','Deep','#8e9db5'],['sleep_rem','REM','#b2a2bf'],['sleep_light','Light','#c9cfdf']].map(([kind,name,color])=>({kind,name,color,row:readings.find(r=>r.kind===kind&&r.observed_at===latest?.observed_at)})).filter(s=>s.row);const total=stages.reduce((a,s)=>a+Number(s.row.value),0);const list=metrics.filter(m=>m.group==='sleep'&&reading(m.kind));return `<div class="page-top"><div><h2>Your night, in perspective.</h2><p>${latest?'Recorded '+new Date(latest.observed_at).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}):'Connect a wearable to see your sleep.'}</p></div><button class="btn light" data-nav="Integrations">Manage sources ${icon('arrow')}</button></div>${stages.length?`<section class="panel sleep-overview"><div><div class="eyebrow">Last recorded night</div><h2>${formatValue(latest.value,'sleep')}<small> hours asleep</small></h2><p>${esc(latest.source)} · Sleep stages</p></div><div class="sleep-stages"><div class="stage-bar">${stages.map(s=>`<i style="flex:${s.row.value};background:${s.color}" title="${s.name}: ${formatValue(s.row.value,s.kind)} hours"></i>`).join('')}</div><div class="stage-legend">${stages.map(s=>`<span><i style="background:${s.color}"></i>${s.name}<strong>${formatValue(s.row.value,s.kind)} h</strong></span>`).join('')}</div></div></section>`:''}<div class="metric-grid full">${cards(list.length?list:metrics.filter(m=>['sleep','sleep_performance','sleep_efficiency'].includes(m.kind)))}</div>`}
function currentBoard(){return boardDraft||normalizeLayout(data.user?.user_metadata?.dashboard_layout,data.user?.user_metadata?.dashboard)}
async function editDashboard(){if(boardDraft)return;boardDraft=structuredClone(currentBoard());page='Home';await render();document.querySelector('#board-add')?.focus();}
async function redrawBoard(focus){await render();if(focus)document.querySelector(focus)?.focus();}
function editTools(){return boardDraft?`<section class="board-toolbar" aria-label="Dashboard editing"><div><span class="eyebrow">Make it yours</span><h2>Your widgets. Your perspective.</h2><p>Drag a handle to rearrange. Choose a size, or add something new.</p></div><div class="actions"><button id="board-add" class="btn light" data-action="add-widgets">${icon('plus')} Add widgets</button><button class="text-button" data-action="cancel-board">Cancel</button><button class="btn" data-action="save-board" ${boardSaving?'disabled':''}>${boardSaving?'Saving…':'Done'}</button></div></section>`:'';}
function bindBoard(){if(!boardDraft)return;bindWidgetEditing($('#page'),{remove:id=>{boardDraft.widgets=boardDraft.widgets.filter(w=>w.id!==id);redrawBoard('#board-add')},resize:(id,size)=>{boardDraft.widgets.find(w=>w.id===id).size=size;redrawBoard(`[data-size-widget="${id}"][data-size="${size}"]`)},move:(id,delta,target)=>{const index=target?boardDraft.widgets.findIndex(w=>w.id===target):boardDraft.widgets.findIndex(w=>w.id===id)+delta;boardDraft.widgets=moveWidget(boardDraft.widgets,id,index);redrawBoard(`[data-drag-widget="${id}"]`)}});}
function widgetGallery(){let group='all',search='';showModal(`${heading('A little more you.','Widget gallery')}<p>Choose what matters. Every widget uses your own recorded data.</p><label class="widget-search"><input id="widget-search" type="search" placeholder="Search widgets" aria-label="Search widgets"></label><div class="widget-categories">${[['all','All'],['vitals','Vitals'],['sleep','Sleep'],['body','Body'],['activity','Activity'],['daily','Daily life']].map(([id,n])=>`<button data-widget-group="${id}" aria-pressed="${id===group}">${n}</button>`).join('')}</div><div id="widget-gallery" class="widget-gallery"></div><p id="widget-count" class="mini-note" role="status"></p>`,true);
 const draw=()=>{const list=widgetCatalog.filter(m=>(group==='all'||m.group===group)&&m.name.toLowerCase().includes(search.toLowerCase()));$('#widget-gallery').innerHTML=list.map(m=>{const added=boardDraft.widgets.some(w=>w.id===m.kind),r=reading(m.kind);return `<button class="widget-choice ${m.color}" data-add-widget="${m.kind}" ${added?'disabled':''}><div class="widget-choice-head"><span>${m.name}</span><b>${added?'✓':'+'}</b></div><div class="widget-preview-number">${r?formatValue(r.value,m.kind):m.kind==='nutrition'?Math.round(totals(mealData).calories):m.kind==='digestive'?'↗':'—'}<small>${m.kind==='nutrition'?'kcal':m.unit}</small></div><small>${added?'On your dashboard':r?esc(r.source):m.group==='daily'?'Your daily view':'Awaiting a connected reading'}</small></button>`}).join('')||'<p>No matching widgets.</p>';$('#widget-count').textContent=`${boardDraft.widgets.length} of 16 widgets added`;document.querySelectorAll('[data-add-widget]').forEach(b=>b.onclick=async()=>{if(boardDraft.widgets.length>=16){toast('Your dashboard holds up to 16 widgets.');return}boardDraft.widgets.push({id:b.dataset.addWidget,size:['nutrition','digestive'].includes(b.dataset.addWidget)?'medium':'small'});await render();draw();});};
 $('#widget-search').oninput=e=>{search=e.target.value;draw()};document.querySelectorAll('[data-widget-group]').forEach(b=>b.onclick=()=>{group=b.dataset.widgetGroup;document.querySelectorAll('[data-widget-group]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));draw()});draw();}
function syncControl(){const last=connections.find(c=>c.provider==='whoop')?.last_synced_at;const detail=syncState.error?'Could not refresh. Select to retry.':syncState.inProgress?'Sync running in another tab':last?'Last WHOOP sync: '+new Date(last).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):syncState.checkedAt?'Records updated '+new Date(syncState.checkedAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'Refresh your records';return `<button class="btn light refresh-data ${syncState.busy?'is-syncing':''} ${syncState.error?'sync-retry':''}" data-action="refresh" aria-label="${syncState.error?'Retry refreshing data':'Refresh data'}" aria-describedby="sync-description" ${syncState.busy?'disabled':''} title="${esc(detail)}">${icon('refresh')}<span>${syncState.busy?'Refreshing':syncState.error?'Retry':'Refresh'}</span></button><span id="sync-description" class="sr-only" role="status">${syncState.busy?'Updating your connected data…':esc(detail)}</span>`;}
function updateSyncControl(){const host=$('#sync-control');if(host){host.innerHTML=syncControl();wire(host);}}
const syncController=createSyncController({loadConnections:async()=>{const s=await data.api('connections');return s.connections||[]},sync:()=>data.api('whoop-sync'),reload:async()=>{await refresh();if(data.user&&!boardDraft&&!$('#onboard-form')&&!chatOpen&&!['Nutrition','Journal'].includes(page))await render()},onState:state=>{if(!data.user)return;syncState={...syncState,...state};updateSyncControl();}});
async function refreshConnected(manual=false){const result=await syncController.run();if(manual)toast(result.ok?result.inProgress?'WHOOP sync is already running. Refresh again shortly.':result.live?'Connected readings refreshed':'Saved records refreshed. Manage sources to connect a wearable.':syncState.error||'Could not refresh. Your saved readings are still available.');}

function bodySignals(){return [['resting_hr','Heart','bpm','heart'],['spo2','Blood oxygen','%','oxygen'],['respiratory_rate','Breathing','/min','breathing']].map(([kind,label,unit,position])=>{const r=reading(kind),copy=`<span class="signal-copy">${label}<strong>${r?formatValue(r.value,kind):'—'} <small>${unit}</small></strong></span>`,point='<span class="signal-line"></span><span class="signal-dot"></span>';return `<button class="body-signal signal-${position}" data-metric="${kind}" aria-label="Explore ${metrics.find(m=>m.kind===kind).name.toLowerCase()}">${position!=='breathing'?copy+point:'<span class="signal-dot"></span><span class="signal-line"></span>'+copy}</button>`}).join('')}
function portrait(signals=false){const image='<img class="human-portrait" src="/images/human-portrait.png" alt="Illustrative portrait of a curly-haired adult in soft natural light" width="1024" height="1536" fetchpriority="high">';return `<div class="portrait-scene ${signals?'portrait-anchored':''}"><div class="portrait-halo"></div>${signals?`<div class="portrait-figure">${image}${bodySignals()}</div>`:image}</div>`}
function hasRepresentation(){return profile?.representation==='digital'||profile?.representation==='photo'}
function personalVisual(){if(profile?.representation==='digital')return '<div id="avatar-host" class="avatar-host personal-model"></div>';if(portraitURL)return `<div class="portrait-scene portrait-anchored personal-portrait"><div class="portrait-halo"></div><div class="portrait-figure"><img class="human-portrait" src="${esc(portraitURL)}" alt="Your personal AI portrait in the Xeyo style">${bodySignals()}</div></div>`;return portrait(true);}
function portraitStudio(){if(!profile?.photo_record_id||profile.representation!=='photo'){choosePortraitPhoto();return;}openPortraitStudio({sourceId:profile.photo_record_id,api:data.api,showModal,heading,closeModal,connect:()=>aiSettings(()=>portraitStudio()),changePhoto:choosePortraitPhoto,accepted:async()=>{await refresh();await render();toast('Your portrait is ready')}});}
function choosePortraitPhoto(){
 if(!profile){profileSetup();return;}
 showModal(`${heading('Start with a photo of you.','Your personal portrait')}<p>Choose a clear photo of yourself with your face and shoulders visible. We use it for your likeness and the original human for the portrait’s lighting and composition.</p><form id="portrait-photo-form"><label class="upload-zone" style="margin-top:24px">${icon('camera')}<span>Choose your photo</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><p class="mini-note">JPG, PNG or WebP · Up to 10 MB · Stored privately. The photo is sent to OpenAI only when you choose Generate.</p><div id="form-error"></div><div class="dialog-footer"><span class="mini-note">Your likeness. Soft light. Bare shoulders.</span><button type="submit" class="btn">Continue to portrait studio ↗</button></div></form>`);
 $('#portrait-photo-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveProfile({...profile,representation:'photo'},e.target.elements.photo.files[0]);await refresh();closeModal();await render();portraitStudio();})};
}
function profileSetup(){dispose();mealLogger.cancel();const previous=profile?.photo_record_id;let photoChanged=false;openOnboarding({app,profile,photos:records.filter(r=>r.kind==='photo'),orb,save:async(draft,file)=>{await data.saveProfile(draft,file);await refresh();photoChanged=profile?.representation==='photo'&&profile?.photo_record_id&&profile.photo_record_id!==previous;},done:async()=>{page='Home';await render();window.scrollTo(0,0);if(photoChanged)portraitStudio();},signOut:actions.logout});}

async function loadPeers(){try{peerResult=await data.peerPercentiles()}catch(e){peerResult={status:'error',message:e.message}}const host=$('#profile-peers');if(page==='Profile'&&host){host.innerHTML=peerPage(peerResult);wire(host);}}
function dashboardWidget(id){if(id==='nutrition')return `<section class="panel nutrition-timeline"><div class="panel-head"><h3>Today’s nutrition</h3><button class="meal-launch" data-action="meal" aria-label="Talk about a meal">${orb()}</button></div><div class="timeline">${'<i></i>'.repeat(12)}</div><div class="axis"><span>6:00</span><span>9:00</span><span>12:00</span><span>15:00</span><span>18:00</span><span>21:00</span></div>${mealData.length?mealData.slice(0,3).map(m=>`<div class="event"><i></i><div>${esc(m.meal_type)}<small>${esc(m.name)}</small></div><span class="right">${Math.round(m.calories)} kcal</span></div>`).join(''):'<div class="empty"><h3>A fresh start</h3><p>Log your first meal to see your day take shape.</p></div>'}</section>`;if(id==='digestive')return journalWidget(journalData,journalError);return cards([metrics.find(m=>m.kind===id)],true);}
function home(){const layout=currentBoard();return `${editTools()}<div class="home-grid ${hasRepresentation()?'':'stats-only'} ${boardDraft?'board-editing':''}">${hasRepresentation()?`<section class="hero-body">${personalVisual()}<div class="hero-overline">A clearer picture.<br>A healthier you.${!portraitURL&&profile?.representation==='photo'?'<small>Illustrative portrait · Personalise in Profile</small>':''}</div><button class="portrait-detail" data-nav="Body">Your measurements ${icon('arrow')}</button></section>`:''}<div class="dashboard-data"><div class="widget-board">${layout.widgets.map((w,i)=>`<div class="widget-slot widget-${w.id} size-${w.size}" data-widget-id="${w.id}">${boardDraft?widgetControls(w,i,layout.widgets.length):''}<div class="widget-content" ${boardDraft?'inert':''}>${dashboardWidget(w.id)}</div></div>`).join('')}${!layout.widgets.length?`<div class="empty-board panel"><h2>A little room for what matters.</h2><p>Add widgets to create your dashboard.</p><button class="btn light" data-action="${boardDraft?'add-widgets':'edit-dashboard'}">${icon('plus')} Add widgets</button></div>`:''}</div></div></div>`}

function nutrition(){const t=totals(mealData),den=t.protein*4+t.carbs*4+t.fat*9,p=den?t.protein*4/den*100:0,c=den?(t.protein+t.carbs)*4/den*100:0;return `<div class="nutrition-workspace"><div class="nutrition-toolbar"><p>A conversation about what nourishes you.</p><label class="nutrition-day-control"><span>Viewing</span><input aria-label="Nutrition day" id="nutrition-day" type="date" max="${localDay()}" value="${nutritionDay}"></label></div><div class="nutrition-canvas"><section class="panel nutrition-assistant" aria-label="Nutrition conversation"><div id="nutrition-chat-host"></div></section><aside class="nutrition-day"><section class="panel daily-balance"><div class="panel-head"><h3>Your daily balance</h3><span class="tag">${mealData.length} ${mealData.length===1?'entry':'entries'}</span></div><div class="balance-summary"><div class="donut ${den?'':'is-empty'}" style="--p:${p}%;--c:${c}%"><span>${Math.round(t.calories)}<small>kcal logged</small></span></div><div class="macro-lines">${[['protein','Protein',p],['carbs','Carbs',c-p],['fat','Fat',den?100-c:0]].map(([k,n,share])=>`<div class="macro-line ${k}"><i></i><span>${n}</span><strong>${Math.round(t[k])}<small> g</small></strong><em>${Math.round(share)}%</em></div>`).join('')}</div></div><p class="mini-note">Estimated from your logged meals.</p></section><section class="panel meal-journal"><div class="panel-head"><h3>Your food journal</h3><span class="journal-date">${new Date(nutritionDay+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><div class="journal-scroll" tabindex="0" aria-label="Meals for the selected day">${mealData.length?mealData.map(m=>`<div class="meal"><span class="meal-icon">${icon('food')}</span><div class="meal-copy"><h3>${esc(m.name)}</h3><p>${esc(m.meal_type)} · ${Math.round(m.protein)} g protein</p></div><div class="kcal">${Math.round(m.calories)}<small>kcal</small></div><button class="icon-btn delete-button" data-delete-meal="${m.id}" aria-label="Delete ${esc(m.name)}">${icon('trash')}</button></div>`).join(''):`<div class="empty">${icon('food')}<h3>Your day starts with a bite.</h3><p>Tell Xeyo what you ate.<br>Your meals will appear here.</p></div>`}</div></section></aside></div></div>`}

function bodyCards(){return metrics.filter(m=>m.group==='body').map(m=>{const r=reading(m.kind);return `<article class="metric body-measurement ${m.color}"><div class="metric-top">${m.name}</div><button class="body-entry-value" data-body-entry="${m.kind}" aria-label="Add ${m.name.toLowerCase()} measurement"><span class="metric-number">${r?formatValue(r.value,m.kind):'—'}<small>${m.unit}</small></span><span class="metric-source">${r?esc(r.source)+' · '+new Date(r.observed_at).toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric'}):'Your measurement, when you’re ready'}</span></button><div class="body-card-actions"><button class="btn light" data-body-entry="${m.kind}">${icon('plus')} Add entry</button>${r?`<button class="text-button" data-metric="${m.kind}">Trend ↗</button>`:''}</div></article>`}).join('')}
function body(){return `<div class="page-top"><div><h2>Your body, in perspective.</h2><p>Measurements you add. Progress you can see.</p></div><button class="btn light" data-action="profile-settings">Change my representation ↗</button></div><div class="body-page ${hasRepresentation()?'':'stats-only'}">${hasRepresentation()?`<section class="panel body-visual">${personalVisual()}<p class="mini-note">${profile.representation==='digital'?'Illustrative digital human':portraitURL?'Your AI portrait':'Illustrative portrait'} · Not a body composition scan</p><button class="text-button" data-action="portrait-studio">Personalise my portrait ↗</button></section>`:''}<section class="body-measurements"><div class="body-card-grid">${bodyCards()}</div><section class="panel body-source-note"><span class="eyebrow">A PICTURE OF YOUR PROGRESS</span><h3>Make your measurements part of the story.</h3><p>Add your weight, body fat or lean mass directly from a scale, a scan or your records. Each entry keeps its date so you can follow changes over time.</p><p class="mini-note">No wearable connection needed. Your portrait is a visual representation, not a measurement.</p></section></section></div>`}
function bodyEntry(kind){openBodyMeasurement({kind,readings,save:data.saveBodyMeasurement,remove:data.removeBodyMeasurement,onChanged:async()=>{await refresh();await render();toast('Measurements updated')},showModal,heading,closeModal,openTrend:metricDetail})}
function reports(){const labFiles=records.filter(r=>r.kind==='lab');return `<div class="page-top"><div><h2>Your records, together.</h2><p>Blood results and original reports, saved to your private account.</p></div><div class="actions">${button(icon('plus')+' Add blood result','lab')}${button(icon('upload')+' Upload report','upload','light')}</div></div><section class="panel"><div class="panel-head"><h3>Blood results</h3><span class="tag">${labResults.length} results</span></div>${labResults.length?`<div class="lab-table-wrap"><table class="lab-table"><thead><tr><th>Test / collected</th><th>Result</th><th>Lab reference</th><th>Status</th><th></th></tr></thead><tbody>${labResults.map(r=>`<tr><td><button class="text-button lab-name" data-lab="${r.id}">${esc(r.marker)}</button><small>${esc(r.collected_on)}${r.laboratory?' · '+esc(r.laboratory):''}</small></td><td><strong>${esc(r.value)}</strong> <small>${esc(r.unit)}</small></td><td>${r.reference_low??'—'} – ${r.reference_high??'—'}</td><td><span class="tag ${['Above reference','Below reference'].includes(labRangeStatus(r))?'warm':''}">${labRangeStatus(r)}</span></td><td><button class="icon-btn" data-lab="${r.id}" aria-label="View ${esc(r.marker)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('vitals')}<h3>Your results, over time</h3><p>Add the value, unit and reference range exactly as printed by your laboratory.</p>${button('Add a blood result','lab','light')}</div>`}</section><section class="panel" style="margin-top:24px"><div class="panel-head"><h3>Lab documents</h3><span class="tag">${labFiles.length} files</span></div>${labFiles.length?labFiles.map(r=>`<div class="record">${icon(r.kind==='photo'?'camera':'report')}<div><h3>${esc(r.name)}</h3><p>${r.kind==='photo'?'Reference photo':'Lab report'} · ${new Date(r.created_at).toLocaleDateString('en-US')}</p></div><div class="actions"><button class="icon-btn" data-download="${r.id}" aria-label="Open ${esc(r.name)}">${icon('arrow')}</button><button class="icon-btn delete-button" data-delete-record="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('trash')}</button></div></div>`).join(''):`<div class="empty">${icon('report')}<h3>A home for your health history</h3><p>Upload a PDF or image. Only your account can access it.</p>${button('Upload a report','upload','light')}</div>`}</section><p class="mini-note">Reference flags compare your entry with the range you provide. They are not a diagnosis. Values with different units are kept separate.</p>`}
function labForm(row={}){showModal(`${heading(row.id?'Edit blood result':'Add a blood result','Health records')}<p>Copy the numeric value and unit exactly from your laboratory report.</p><form id="lab-form" style="margin-top:22px"><div class="form-grid"><label class="field">Test name<input name="marker" required maxlength="120" placeholder="e.g. Ferritin" value="${esc(row.marker||'')}"></label><label class="field">Collection date<input name="collected_on" type="date" required max="${localDay()}" value="${row.collected_on||localDay()}"></label><label class="field">Result<input name="value" type="number" required min="0" max="1000000000" step="any" value="${row.value??''}"></label><label class="field">Unit<input name="unit" required maxlength="40" placeholder="e.g. ng/mL" value="${esc(row.unit||'')}"></label><label class="field">Lower reference limit (optional)<input name="reference_low" type="number" min="0" step="any" value="${row.reference_low??''}"></label><label class="field">Upper reference limit (optional)<input name="reference_high" type="number" min="0" step="any" value="${row.reference_high??''}"></label></div><label class="field">Laboratory (optional)<input name="laboratory" maxlength="160" value="${esc(row.laboratory||'')}"></label><label class="field">Notes (optional)<textarea name="notes" maxlength="2000">${esc(row.notes||'')}</textarea></label><div id="form-error"></div><div class="dialog-footer"><p>Saved privately to your account.</p><button class="btn" type="submit">Save result</button></div></form>`);$('#lab-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveLabResult(Object.fromEntries(new FormData(e.target)),row.id);await refresh();closeModal();page='Blood records';await render();toast('Blood result saved')})}}
function labDetail(id){const r=labResults.find(r=>r.id===id);if(!r)return;const history=labResults.filter(x=>x.marker.toLowerCase()===r.marker.toLowerCase()&&x.unit===r.unit).sort((a,b)=>a.collected_on.localeCompare(b.collected_on));showModal(`${heading(esc(r.marker),'Blood results / '+esc(r.laboratory||'Your report'))}<p>${esc(r.collected_on)} · Entered from your laboratory report</p><div class="figure-number">${esc(r.value)}<small> ${esc(r.unit)}</small></div><span class="tag">${labRangeStatus(r)}</span><p style="margin-top:18px">Laboratory reference: ${r.reference_low??'—'} – ${r.reference_high??'—'} ${esc(r.unit)}</p><div class="trend-chart">${seriesChart(history.map(x=>({value:x.value,observed_at:x.collected_on+'T12:00:00Z'})))}</div><div class="axis"><span>${history[0]?.collected_on||''}</span><span>${history.at(-1)?.collected_on||''}</span></div><p class="mini-note">${history.length} result(s) in ${esc(r.unit)}. Reference ranges may change between laboratories.</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}<div class="dialog-footer"><button class="btn light" id="edit-lab">Edit result</button><button class="text-button" id="delete-lab">Delete result</button></div>`);$('#edit-lab').onclick=()=>labForm(r);$('#delete-lab').onclick=()=>{showModal(`${heading('Delete this blood result?')}<p>This permanently removes ${esc(r.marker)} collected on ${esc(r.collected_on)}.</p><div class="dialog-footer">${button('Keep result','close','light')}<button class="btn" id="confirm-lab-delete">Delete result</button></div>`);$('#confirm-lab-delete').onclick=async()=>{try{$('#confirm-lab-delete').disabled=true;await data.removeLabResult(id);await refresh();closeModal();await render();toast('Result deleted')}catch(e){err(e)}}}}
function importWearable(provider){openWearableImport(provider,{showModal,heading,icon,api:data.api,done:async count=>{closeModal();await refresh();await render();toast(count+' measurements imported')}})}

function integrations(){const whoop=connections.find(c=>c.provider==='whoop');return `<div class="page-top"><div><h2>Bring your health together.</h2><p>Your account. Your measurements. Your choice.</p></div></div><div class="integrations"><section class="integration"><div class="integration-logo">W</div><h2>WHOOP</h2><span class="tag ${whoop?'':'warm'}">${whoop?'Connected':capabilities.whoop?'Ready to connect':'Activation pending'}</span><p>Recovery, sleep, resting heart rate, HRV, blood oxygen and respiratory rate. Includes skin temperature, sleep stages, efficiency and consistency. Imports up to 90 days.</p>${whoop?`<p class="mini-note">${whoop.last_synced_at?'Last synced '+new Date(whoop.last_synced_at).toLocaleString('en-US'):'First synchronization pending'}</p>`:''}${whoop?button('Sync now','sync-whoop','light')+button('Disconnect','disconnect-whoop','light'):capabilities.whoop?button('Connect WHOOP','whoop','light'):'<p class="mini-note">WHOOP authorization is being configured. Connecting will become available here when activated.</p>'}</section><section class="integration"><div class="integration-logo">G</div><h2>Fitbit / Google Health</h2><span class="tag">${readings.some(r=>r.source.startsWith('Fitbit import'))?'Data imported':'File import available'}</span><p>Import recorded heart rate, sleep, HRV, weight and body-fat measurements from your data export.</p>${button('Import Fitbit data','import-fitbit','light')}<small class="integration-mode">Automatic sync needs an approved Google Health app.</small></section><section class="integration"><div class="integration-logo">⌘</div><h2>Apple Watch / Health</h2><span class="tag">${readings.some(r=>r.source.startsWith('Apple Health import'))?'Data imported':'File import available'}</span><p>Import heart rate, HRV, oxygen, breathing and scale measurements from your iPhone Health export.</p>${button('Import Apple Health','import-apple','light')}<small class="integration-mode">Automatic sync needs an iPhone companion app.</small></section></div>${connectionError?`<p class="error">Could not check connection status: ${esc(connectionError)} ${button('Try again','refresh','light')}</p>`:''}<section class="panel" style="margin-top:24px"><h3>Measured. Always clear.</h3><p style="margin-top:10px">Every reading keeps its source and date. Disconnecting stops access; previously imported measurements stay in your records. Nutrition logs do not measure glucose, inflammation or water retention.</p></section>`}
function settings(){return `<section class="panel"><h2>Your profile</h2><div class="settings-row"><div><h3>Your profile & perspective</h3><p>${profile?esc(({photo:"Personal portrait",digital:"Digital human",stats:"Statistics only"})[profile.representation])+" · "+profile.age+" years":"Personalize your workspace"}</p><p class="mini-note">Peer comparisons ${profile?.peer_opt_in?"enabled":"off"}. Change your image, age or participation anytime.</p></div>${button("Edit preferences","profile-settings","light")}${profile?.representation==='photo'?button("Portrait studio","portrait-studio","light"):''}</div><div class="settings-row"><div><h3>Chatbot</h3><p>Choose OpenAI, Claude or Gemini and connect your own API key.</p></div><button class="btn light" data-action="chat-connect">Manage chatbot AI</button></div><div class="settings-row"><div><h3>Account</h3><p>${esc(data.user.email)}</p></div><span class="tag">Signed in</span></div><div class="settings-row"><div><h3>OpenAI · Nutrition & portraits</h3><p>${capabilities.personalAI?'Your OpenAI API key is connected. Usage is billed to your OpenAI account.':'Connect your own OpenAI API key for meal photos, descriptions and voice notes.'}</p></div>${button(capabilities.personalAI?'Manage AI key':'Connect AI key','ai-settings','light')}</div><div class="settings-row"><div><h3>Connected sources</h3><p>Manage what comes into your health profile.</p></div><button class="btn light" data-nav="Integrations">Manage sources</button></div><div class="settings-row"><div><h3>Export your data</h3><p>Download your complete meal history, readings, lab results and file metadata.</p></div>${button('Download JSON','export','light')}</div><div class="settings-row"><div><h3>Privacy & data use</h3><p>Understand how files, food descriptions and recordings are handled.</p></div>${button('Read details','privacy','light')}</div><div class="settings-row"><div><h3>End your session</h3><p>Sign out on this device.</p></div>${button('Sign out','logout','light')}</div></section><details class="panel profile-section"><summary>${icon('peers')} Your age-group comparison <span>Private to you</span></summary><div id="profile-peers">${peerPage(peerResult)}</div></details><details class="panel profile-section"><summary>${icon('camera')} Your portrait photos <span>${records.filter(r=>r.kind==='photo').length} files</span></summary><p class="mini-note">Private reference photos for your portrait. These are separate from blood records.</p>${records.filter(r=>r.kind==='photo').map(r=>`<div class="record">${icon('camera')}<div><h3>${esc(r.name)}</h3><p>Reference photo · ${new Date(r.created_at).toLocaleDateString('en-US')}</p></div><div class="actions"><button class="icon-btn" data-download="${r.id}" aria-label="Open ${esc(r.name)}">${icon('arrow')}</button><button class="icon-btn delete-button" data-delete-record="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('trash')}</button></div></div>`).join('')||'<p class="mini-note">Your reference photos will appear here.</p>'}</details>`}
async function refresh(){const owner=data.user?.id;if(!owner)return;const next=await Promise.all([data.meals(nutritionDay),data.readings(),data.records(),data.labResults(),data.profile()]);if(data.user?.id!==owner)return;[mealData,readings,records,labResults,profile]=next;portraitURL=await data.profilePhoto(profile);portraitChecked=Date.now();try{journalData=await data.journalEntries();journalError=''}catch(e){journalError=e.message}peerResult=null;connections=[];connectionError='';try{const status=await data.api('connections');if(data.user?.id!==owner)return;connections=status.connections||[];capabilities=status.capabilities||{}}catch(e){connectionError=e.message}}

function accountMenu(name,compact=false){return `<details class="account-menu ${compact?'compact':'sidebar-account'}"><summary aria-label="${compact?'Account menu':'Profile menu'}"><span class="avatar-letter">${esc(name.slice(0,1).toUpperCase())}</span>${compact?'':`<span class="account-name">${esc(name)}<small>Your profile</small></span><span class="account-chevron">⌃</span>`}</summary><div class="account-popover"><span class="eyebrow">YOUR WORKSPACE</span><button data-nav="Profile">${icon('body')} Profile</button><button data-nav="Integrations">${icon('link')} Integrations</button><button data-action="privacy">${icon('shield')} Privacy & data</button><button data-action="logout">${icon('logout')} Sign out</button></div></details>`}
function chatDock(){return `<div id="chat-dock" class="chat-dock ${chatOpen?'is-open':''}"><section class="chat-window" aria-label="Xeyo chatbot" ${chatOpen?'':'hidden'}><div class="chat-window-bar"><span>${orb()} Ask Xeyo</span><button class="icon-btn" data-action="close-chat" aria-label="Close chatbot">${icon('close')}</button></div><div id="chatbot-host"></div></section><button class="chat-launcher" data-action="toggle-chat" aria-expanded="${chatOpen}" aria-label="${chatOpen?'Close chatbot':'Open chatbot'}">${orb()}<span>Ask Xeyo<small>A little more clarity</small></span>${icon('chat')}</button></div>`}
async function toggleChat(force){chatOpen=force??!chatOpen;if(page!=='Home'){page='Home';await render();return}const dock=$('#chat-dock');if(!dock)return;dock.outerHTML=chatDock();wire($('#chat-dock'));if(chatOpen){await chatbot.mount();$('#chat-message')?.focus()}else document.querySelector('.chat-launcher')?.focus();}
async function render(){const previousChat=page==='Home'?$('#chat-dock'):null;dispose();if(profile?.representation==='photo'&&Date.now()-portraitChecked>55*60000){portraitURL=await data.profilePhoto(profile);portraitChecked=Date.now();}const name=data.user?.user_metadata?.name||data.user?.email?.split('@')[0]||'there';app.innerHTML=`<aside class="sidebar"><button class="brand" data-nav="Home" aria-label="Xeyo — home">${orb()}<span class="brand-name">Xeyo</span></button><nav class="nav">${navs.map(([n,i])=>`<button class="${page===n?'active':''}" data-nav="${n}" aria-label="${n}" ${page===n?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom">${accountMenu(name)}</div></aside><main class="shell ${page==='Home'&&!boardDraft&&boardRows(currentBoard())<=3?'home-fitted':''}" data-page="${page}"><header class="header"><div>${page==='Home'?`<div class="hello">Hello,</div><h1>${esc(name)}.</h1><p>Here’s your health today.</p>`:`<h1>${page}</h1><p>Your health, in perspective.</p>`}</div><div class="header-actions"><span>${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><div id="sync-control">${syncControl()}</div>${page==='Home'?`<button class="btn light edit-dashboard" data-action="edit-dashboard" aria-label="Edit dashboard">${icon('settings')}<span>Edit widgets</span></button>`:''}${accountMenu(name,true)}</div></header><div id="page">${page==='Home'?home():page==='Nutrition'?nutrition():page==='Body'?body():page==='Blood records'?reports():page==='Integrations'?integrations():page==='Profile'?settings():page==='Journal'?'<div id="journal-host"></div>':`${page==='Sleep'?sleepPage():vitalsPage()}`}</div><footer class="footer"><span>A little more clarity, every day.</span><span>Personal health records · Not a diagnosis</span></footer>${page==='Home'?chatDock():''}</main>`;if(previousChat&&chatOpen)$('#chat-dock').replaceWith(previousChat);wire();bindBoard();mountModel();if(page==='Nutrition')mealLogger.refresh();if(page==='Profile')loadPeers();if(page==='Home'&&chatOpen&&!previousChat)chatbot.mount();if(page==='Journal')journal.mount()}
function showModal(html,wide=false){lastFocus=document.activeElement;$('#modal').innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="icon-btn close" data-action="close" aria-label="Close">${icon('close')}</button>${html}</section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';wire($('#modal'));$('.close').focus()}
function cancelRecording(){mealLogger.cancel()}
function closeModal(){cancelRecording();cancelImport();$('#modal').hidden=true;$('#modal').innerHTML='';document.body.style.overflow='';lastFocus?.focus()}
function heading(t,s='Your health, in perspective'){return `<div class="eyebrow">${s}</div><h2 id="dialog-title">${t}</h2>`}
function aiSettings(afterSave){
 showModal(`${heading('Your OpenAI connection.','Settings / Your OpenAI connection')}<p>Connect your own OpenAI API key for meal logging and your personal portrait.</p><div class="ai-key-info"><span class="tag ${capabilities.personalAI?'':'warm'}">${capabilities.personalAI?'Connected':'Not connected'}</span><p>Your key is encrypted on our server and used only for your requests. API usage is billed to your OpenAI account.</p></div><form id="ai-key-form"><label class="field">${capabilities.personalAI?'Replace OpenAI API key':'OpenAI API key'}<input name="key" type="password" required autocomplete="off" spellcheck="false" placeholder="sk-…" minlength="20" maxlength="384"></label><p class="mini-note">Create a key in <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener">your OpenAI account ↗</a>. The project needs API billing and access to the nutrition, transcription and gpt-image-2 image models. A ChatGPT subscription alone is not an API connection.</p><div id="form-error"></div><div class="dialog-footer"><span class="meal-private">${icon('shield')} Stored encrypted</span><button class="btn" type="submit">${capabilities.personalAI?'Replace key':'Connect key'} ${icon('arrow')}</button></div></form>${capabilities.personalAI?'<button class="text-button remove-ai-key" id="remove-ai-key">Remove my key from this app</button>':''}`);
 $('#ai-key-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const input=e.target.elements.key;let key=input.value.trim();try{await data.api('ai-key-save',{key})}finally{input.value='';key=''}await refresh();closeModal();await render();toast('Your OpenAI key is connected');afterSave?.()})};
 if($('#remove-ai-key'))$('#remove-ai-key').onclick=()=>{showModal(`${heading('Remove your API connection?')}<p>This deletes the stored key from this app. Your saved meals stay in your journal. To revoke the key everywhere, also remove it in your OpenAI account.</p><div id="form-error"></div><form id="remove-ai-form"><div class="dialog-footer">${button('Keep connection','close','light')}<button class="btn" type="submit">Remove key</button></div></form>`);$('#remove-ai-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.api('ai-key-remove');await refresh();closeModal();await render();toast('API key removed')})}};
}
const journal=createJournal({getCapabilities:()=>capabilities,load:data.journalEntries,save:data.saveJournal,remove:data.deleteJournal,removeReflection:data.deleteReflection,api:data.api,orb,showModal,heading,closeModal,onChanged:async entries=>{journalData=entries;journalError=''},bindNav:root=>wire(root)});
const chatbot=createChatbot({api:data.api,loadMessages:data.chatMessages,orb,showModal,heading,closeModal,bindNav:()=>wire($('#chatbot-host'))});
const mealLogger=createMealLogger({showModal,getHost:()=>page==='Nutrition'?$('#nutrition-chat-host'):null,heading,icon,api:data.api,getDay:()=>nutritionDay,getCapabilities:()=>capabilities,connectAI:()=>aiSettings(()=>openMeal()),save:async rows=>{const saved=await data.saveMeals(rows);await refresh();await render();return saved},remove:async ids=>{await data.removeMeals(ids);await refresh();await render()},update:async rows=>{await data.updateMeals(rows);await refresh();await render()}});
async function openMeal(){if(page!=='Nutrition'){page='Nutrition';await render();window.scrollTo(0,0)}$('#meal-description')?.focus()}
function formError(e){let target=$('#form-error');if(target)target.innerHTML=`<div class="error">${esc(e.message)}</div>`;else err(e)}
function busy(form,promise){const b=form.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;return promise().catch(formError).finally(()=>b.disabled=false)}
function upload(kind='lab'){showModal(`${heading(kind==='lab'?'Add a lab report':'Add a reference photo','Private records')}<p>${kind==='photo'?'Photos are stored privately as references. They are not used to infer body fat or reconstruct your body.':'Your original report will be stored privately. Automatic interpretation is not enabled.'}</p><form id="upload-form"><label class="upload-zone" style="margin-top:20px">${icon('upload')}<span>Choose a ${kind==='photo'?'photo':'PDF or image'}</span><input name="file" type="file" accept="${kind==='photo'?'image/jpeg,image/png,image/webp':'application/pdf,image/jpeg,image/png,image/webp'}" required></label><p class="mini-note">Up to 10 MB. Uploaded to your account’s private storage.</p><div id="form-error"></div><div class="dialog-footer"><p>Visible only to your account</p><button class="btn" type="submit">Upload privately</button></div></form>`);$('#upload-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.uploadRecord(new FormData(e.target).get('file'),kind);closeModal();await refresh();page='Blood records';await render();toast('Record uploaded')})}}
function metricDetail(kind){if(['weight','body_fat','lean_mass'].includes(kind)&&!reading(kind)){bodyEntry(kind);return}openMetricDetail({metric:metrics.find(m=>m.kind===kind),reading:reading(kind),readings,showModal,heading})}
function privacy(){showModal(`${heading('Your data, your choice','Privacy')}<p>Your profile preferences, private chatbot history and signed-in records are stored in the configured Supabase project and protected by account ownership policies. Files use a private bucket and short-lived download links.</p><div class="settings-row"><div><h3>Food descriptions, labels & audio</h3><p>Sent to OpenAI using your own API key when you request analysis or finish recording. Meal photos and audio are not saved to your journal; estimated macros are saved to your journal. You can edit values or undo a logged meal.</p></div></div><div class="settings-row"><div><h3>Photos and lab reports</h3><p>Stored privately. Portrait generation sends your selected photo and the style reference to OpenAI when you choose Generate. The result is private and shown only after you approve it. Photos are not used to detect body fat; reports are not automatically diagnosed.</p></div></div><p class="mini-note"><a href="/privacy.html" target="_blank" rel="noopener">Read the full data-use notice ↗</a> · For account deletion: <a href="mailto:tobia@donadon.com">tobia@donadon.com</a></p>`)}
const actions={'toggle-chat':()=>toggleChat(),'close-chat':()=>toggleChat(false),'chat-connect':()=>chatbot.connect(),'portrait-studio':portraitStudio,'add-widgets':widgetGallery,'cancel-board':async()=>{boardDraft=null;await render()},'save-board':async()=>{if(boardSaving)return;boardSaving=true;try{await data.saveDashboardLayout(boardDraft);boardDraft=null;await render();toast('Dashboard saved')}finally{boardSaving=false}},'profile-settings':profileSetup,'retry-peers':loadPeers,'import-apple':()=>importWearable('apple'),'import-fitbit':()=>importWearable('fitbit'),'edit-dashboard':editDashboard,'ai-settings':()=>aiSettings(),lab:()=>labForm(),refresh:()=>refreshConnected(true),'portrait-view':()=>{bodyView='portrait';render()},'model-view':()=>{bodyView='model';render()},digestive:()=>{page='Journal';render()},'digestive-nutrition':()=>{closeModal();page='Nutrition';render()},'digestive-reports':()=>{closeModal();page='Blood records';render()},'sync-whoop':()=>refreshConnected(true),'disconnect-whoop':async()=>{await data.api('whoop-disconnect');await refresh();render();toast('WHOOP access revoked. Previously imported readings are retained.')},close:closeModal,meal:()=>openMeal(),upload:()=>upload(),photo:()=>upload('photo'),privacy,logout:async()=>{await data.signOut();chatOpen=false;boardDraft=null;syncState={busy:false,error:null};chatbot.reset();journal.reset();journalData=[];journalError='';profile=null;portraitURL=null;peerResult=null;emailFlow.clear();history.replaceState({},'',location.pathname);closeModal();showAuth()},appearance:()=>{appearance={skinColor:$('#skin').value};avatar?.setAppearance(appearance);toast('Display material updated')},whoop:async()=>{const r=await data.api('whoop-connect');if(!r.url?.startsWith('https://api.prod.whoop.com/oauth/oauth2/auth?'))throw Error('Invalid authorization destination.');location.assign(r.url)},google:()=>showModal(`${heading('Fitbit via Google Health','Integration setup')}<p>The legacy Fitbit API retires October 30, 2026. This application needs an approved Google Health API project before live Fitbit synchronization can be enabled.</p><p style="margin-top:20px"><a href="https://developers.google.com/health" target="_blank" rel="noopener">Google Health developer setup ↗</a></p>`),apple:()=>showModal(`${heading('Apple Watch & Apple Health','iPhone companion required')}<p>A website cannot directly read HealthKit. An iPhone companion app must request your permission and securely upload the specific measurements you choose.</p><p style="margin-top:20px">The native companion and background synchronization are not part of this deployed web build. No Apple Health connection is claimed.</p>`),'to-integrations':()=>{closeModal();page='Integrations';render()},export:async()=>{const blob=new Blob([JSON.stringify(await data.exportAll(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='health-records-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}};

function wire(root=app){if(!root)return;root.querySelectorAll('[data-body-entry]').forEach(b=>b.onclick=()=>bodyEntry(b.dataset.bodyEntry));const day=root.querySelector('#nutrition-day');if(day)day.onchange=async()=>{if(!day.value)return;mealLogger.cancel();nutritionDay=day.value;try{mealData=await data.meals(nutritionDay);await render()}catch(e){err(e)}};root.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>labDetail(b.dataset.lab));root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='Chatbot'){toggleChat(true).catch(err);return;}if(b.dataset.nav!=='Home')chatOpen=false;if(page==='Nutrition'&&b.dataset.nav!==page)mealLogger.cancel();if(b.dataset.nav!==page)boardDraft=null;page=b.dataset.nav;if(page==='Home'&&nutritionDay!==localDay()){nutritionDay=localDay();data.meals(nutritionDay).then(rows=>{mealData=rows;render()}).catch(err)}render().then(()=>window.scrollTo(0,0)).catch(err)});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;document.querySelectorAll('.account-menu[open]').forEach(el=>el.open=false);b.disabled=true;try{await actions[b.dataset.action]?.()}catch(e){err(e)}finally{if(b.isConnected)b.disabled=false}});root.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>metricDetail(b.dataset.metric));root.querySelectorAll('[data-delete-meal]').forEach(b=>b.onclick=async()=>{try{await data.removeMeal(b.dataset.deleteMeal);await refresh();render();toast('Meal removed')}catch(e){err(e)}});root.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const url=await data.downloadRecord(b.dataset.download);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click()}catch(e){err(e)}});root.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteRecord;showModal(`${heading('Delete this record?','Private records')}<p>This removes the stored file and its record. This cannot be undone.</p><div class="dialog-footer">${button('Keep record','close','light')}<button class="btn" id="confirm-delete">Delete record</button></div>`);$('#confirm-delete').onclick=async()=>{try{$('#confirm-delete').disabled=true;await data.deleteRecord(id);closeModal();await refresh();render();toast('Record deleted')}catch(e){err(e)}}})}
let authTimer = null, authBusy = false, enteringAccount = false;
let emailStorage;
try { emailStorage = window.sessionStorage; } catch { emailStorage = null; }
const emailFlow = createEmailFlow(data.db?.auth, emailStorage);

function authNotice(message, success=false) {
  const target=$('#auth-message');
  if(target)target.innerHTML=`<div class="error ${success?'success':''}" role="${success?'status':'alert'}">${esc(message)}</div>`;
}
function renderEmailCooldown() {
  const b=$('#resend-email'), input=$('#verification-email');
  if(!b||!input)return;
  const remaining=emailFlow.waitSeconds(input.value, emailFlow.get()?.type||'signup');
  b.disabled=authBusy||remaining>0||!data.configured;
  b.textContent=authBusy?'Sending…':remaining>0?`Resend in ${remaining>=60?Math.ceil(remaining/60)+' min':remaining+'s'}`:emailFlow.get()?.type==='recovery'?'Resend reset email':'Resend verification email';
  const status=$('#email-wait');
  if(status)status.textContent=remaining>0?'A short pause prevents duplicate emails. Your existing link can still be used.':'Check Spam as well. If you requested several links, use the newest one.';
}
async function enterAccount() {
  if(enteringAccount)return;
  enteringAccount=true;
  try {
  await data.session();
  if(!data.user)throw Error('Sign in to continue.');
  emailFlow.clear();clearInterval(authTimer);authMode='account';
  const connectionResult=new URLSearchParams(location.search).get('connection');
  history.replaceState({},'',location.pathname);
  await refresh();if(!profile){profileSetup();void refreshConnected();return;}page=connectionResult?'Integrations':'Home';await render();window.scrollTo(0,0);void refreshConnected();
  if(connectionResult)toast(connectionResult==='connected'?'WHOOP connected and synchronized':connectionResult==='denied'?'WHOOP authorization was cancelled':connectionResult==='connected-needs-sync'?'WHOOP connected. Choose Sync now to import readings.':'WHOOP connection could not be completed. Try again.');
  } finally { enteringAccount=false; }
}
function showAuth(mode='login') {
  clearInterval(authTimer);authMode=mode;dispose();mealLogger.cancel();
  const pending=emailFlow.get(),verify=mode==='verify',recovery=verify&&pending?.type==='recovery';
  const titles={signup:'Make room for you.',forgot:'A fresh start.',reset:'Choose a new password.',verify:recovery?'Check your inbox.':'Confirm your email.',login:'Welcome back.'};
  const description=verify?(recovery?'Open the password-reset link to choose a new password.':'Open the confirmation link in your inbox to activate your private workspace.'):
    mode==='signup'?'Create your private health workspace.':mode==='forgot'?'We’ll send you a secure password-reset link.':mode==='reset'?'Use a unique password with at least 12 characters.':'A clearer picture of your health starts here.';
  const verification=`<div class="verification-symbol">${icon('shield')}</div><div class="verification-steps"><span class="${pending?.delivery==='requested'?'done':''}">1 · Email requested</span><span class="current">2 · Confirm email</span><span>3 · Sign in</span></div><form id="verification-form"><label class="field">Email address<input id="verification-email" name="email" type="email" autocomplete="email" required value="${esc(pending?.email||'')}" placeholder="you@example.com"></label><div id="auth-message" aria-live="polite"></div><button class="btn light" id="resend-email" type="submit">Resend verification email</button><p class="mini-note" id="email-wait"></p></form><button class="btn verified-login" id="verified-login">${recovery?'Back to sign in':'I’ve confirmed my email · Sign in'} ${icon('arrow')}</button><div class="auth-options"><button class="text-button" id="change-email">Use a different email</button></div>`;
  const form=`<form id="auth-form">${mode==='signup'?'<label class="field">Your name<input name="name" autocomplete="given-name" required maxlength="60" placeholder="First name"></label>':''}${mode!=='reset'?`<label class="field">Email address<input type="email" name="email" autocomplete="email" required value="${mode==='login'?esc(pending?.email||''):''}" placeholder="you@example.com"></label>`:''}${mode!=='forgot'?`<label class="field">Password<input type="password" name="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?1:12}" maxlength="128" required placeholder="${mode==='login'?'Your password':'At least 12 characters'}"></label>`:''}${['signup','reset'].includes(mode)?'<label class="field">Confirm password<input type="password" name="confirm" autocomplete="new-password" minlength="12" required placeholder="Enter your password again"></label>':''}${mode==='signup'?'<label class="privacy-check"><input name="consent" type="checkbox" required><span>I understand this stores personal health information. <button type="button" class="text-button" data-action="privacy">Read data-use details</button></span></label>':''}<div id="auth-message" aria-live="polite"></div><button class="btn" type="submit" ${!data.configured?'disabled':''}>${mode==='signup'?'Create account':mode==='forgot'?'Send reset link':mode==='reset'?'Update password':'Sign in'} ${icon('arrow')}</button></form><div class="auth-options"><button class="text-button" id="switch-auth">${mode==='login'?'Create an account':'Back to sign in'}</button>${mode==='login'?'<button class="text-button" id="forgot">Forgot password?</button>':''}</div>${mode==='login'&&data.emailConfirmation?'<button class="text-button confirmation-help" id="confirm-help">Still waiting for your confirmation email?</button>':''}`;
  app.innerHTML=`<main class="auth-layout"><section class="auth-art"><div class="brand" aria-label="Xeyo">${orb()}<span class="brand-name">Xeyo</span></div>${portrait()}<div class="auth-copy"><h1>A little more clarity.<br>A healthier you.</h1><p>Your daily signals, nutrition and health records, together in Xeyo.</p></div></section><section class="auth-form"><div class="auth-inner"><div class="eyebrow">YOUR HEALTH, IN PERSPECTIVE</div><h1>${titles[mode]||titles.login}</h1><p>${description}</p>${!data.configured?'<div class="config-note">Account services are not connected yet.</div>':data.testMode?'<div class="config-note">Private beta. Verification email is currently enabled for approved test addresses.</div>':''}${verify?verification:form}</div></section></main>`;
  wire();window.scrollTo(0,0);
  if(verify){
    renderEmailCooldown();authTimer=setInterval(renderEmailCooldown,1000);
    $('#verification-email').oninput=renderEmailCooldown;
    $('#verified-login').onclick=()=>showAuth('login');
    $('#change-email').onclick=()=>showAuth(recovery?'forgot':'signup');
    $('#verification-form').onsubmit=async e=>{
      e.preventDefault();if(authBusy)return;
      const email=$('#verification-email').value.trim();
      if(emailFlow.waitSeconds(email,recovery?'recovery':'signup'))return;
      authBusy=true;renderEmailCooldown();
      try{const result=await emailFlow.send({email,type:recovery?'recovery':'signup',origin:location.origin});
        authNotice(result.limited?'Email requests are temporarily limited. Use the link already in your inbox, or wait for the timer.':'If this address has a pending account, a new link has been requested. Check your inbox and Spam.',!result.limited);
      }catch(e){authNotice(authMessage(e))}finally{authBusy=false;renderEmailCooldown()}
    };
    return;
  }
  $('#switch-auth').onclick=()=>showAuth(mode==='login'?(data.emailConfirmation&&emailFlow.get()?.type==='signup'?'verify':'signup'):'login');
  if($('#forgot'))$('#forgot').onclick=()=>showAuth('forgot');
  if($('#confirm-help'))$('#confirm-help').onclick=()=>{if(emailFlow.get()?.type==='recovery')emailFlow.clear();showAuth('verify')};
  $('#auth-form').onsubmit=async e=>{
    e.preventDefault();if(authBusy)return;
    const form=e.target,submit=form.querySelector('[type=submit]'),v=Object.fromEntries(new FormData(form));
    authBusy=true;submit.disabled=true;submit.textContent='Please wait…';
    try{
      if(!data.configured)throw Error('Account services are not configured.');
      if(v.confirm!==undefined&&v.confirm!==v.password)throw Error('Passwords do not match.');
      if(mode==='signup'||mode==='forgot'){
        const result=await emailFlow.send({email:v.email,type:mode==='forgot'?'recovery':'signup',signup:mode==='signup'?{name:v.name,password:v.password}:undefined,origin:location.origin});
        if(result.session){await enterAccount();return;}
        form.reset();showAuth('verify');
        authNotice(result.limited?'A verification request was made recently. Check your inbox before requesting another link.':'Check your inbox and Spam for the secure link. You can close this page and return after confirming.',!result.limited);
        return;
      }
      const result=mode==='reset'?await data.db.auth.updateUser({password:v.password}):await data.db.auth.signInWithPassword({email:v.email.trim(),password:v.password});
      if(result.error)throw result.error;
      form.reset();await enterAccount();
    }catch(error){
      if(error.code==='email_not_confirmed') {emailFlow.remember(v.email);form.reset();showAuth('verify');authNotice('Your email still needs to be confirmed. Use the link in your inbox, or request a new one.');}
      else authNotice(authMessage(error));
    }finally{
      authBusy=false;
      if(submit.isConnected){submit.disabled=!data.configured;submit.textContent=mode==='signup'?'Create account':mode==='forgot'?'Send reset link':mode==='reset'?'Update password':'Sign in';}
      renderEmailCooldown();
    }
  };
}
$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').hidden){const els=[...$('#modal').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
async function start(){
  try{
    await data.session();
    const query=new URLSearchParams(location.search),hash=new URLSearchParams(location.hash.slice(1));
    if(query.has('error')||hash.has('error')){history.replaceState({},'',location.pathname);showAuth('verify');authNotice('This email link has expired or has already been used. Try signing in, or request a new link.');return;}
    if(query.get('reset')==='1'){showAuth('reset');if(!data.user)authNotice('Open a valid password-reset link from your email before changing your password.');return;}
    if(data.user){await enterAccount();}
    else showAuth(data.emailConfirmation&&emailFlow.get()?'verify':'login');
  }catch(e){showAuth();authNotice(authMessage(e));}
}
if(data.db)data.db.auth.onAuthStateChange((event,session)=>{
  if(event==='PASSWORD_RECOVERY')setTimeout(()=>showAuth('reset'),0);
  if(event==='SIGNED_OUT')setTimeout(()=>{journal.reset();journalData=[];journalError='';showAuth()},0);
  if(event==='SIGNED_IN'&&session&&!authBusy&&['login','verify'].includes(authMode))setTimeout(()=>enterAccount().catch(e=>authNotice(authMessage(e))),0);
});
start();

document.addEventListener('click',e=>document.querySelectorAll('.account-menu[open]').forEach(el=>{if(!el.contains(e.target))el.open=false}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').hidden){const open=document.querySelector('.account-menu[open]');if(open){open.open=false;open.querySelector('summary').focus()}else if(chatOpen)toggleChat(false)}});
